import Foundation
import CuyScoutCore
import Darwin
import Network

private struct ArtifactReplayRequest: Decodable {
    var optimized: Bool?
    var variables: [String: String]?
    var resilient: Bool?
    var resetApp: Bool?
    var appPath: String?
    var deviceID: String?
    var preparation: ReplayPreparationMode?
}

final class ScoutHTTPServer: @unchecked Sendable {
    private let port: UInt16; private let engine: ScoutEngine; private let token: String?; private let bindAddress: String; private let tlsCertPath: String?; private let tlsKeyPath: String?
    init(port: UInt16, engine: ScoutEngine, token: String? = nil, bindAddress: String = "127.0.0.1", tlsCertPath: String? = nil, tlsKeyPath: String? = nil) throws { self.port = port; self.engine = engine; self.token = token; self.bindAddress = bindAddress; self.tlsCertPath = tlsCertPath; self.tlsKeyPath = tlsKeyPath }

    func start() throws {
        if tlsCertPath != nil, tlsKeyPath != nil { try startTLS(); return }
        let socketFD = socket(AF_INET, SOCK_STREAM, 0); guard socketFD >= 0 else { throw ScoutError.commandFailed("No se pudo abrir el servidor") }
        var option: Int32 = 1; setsockopt(socketFD, SOL_SOCKET, SO_REUSEADDR, &option, socklen_t(MemoryLayout<Int32>.size))
        let resolvedAddress = inet_addr(bindAddress); guard resolvedAddress != INADDR_NONE else { close(socketFD); throw ScoutError.invalidRequest("Dirección de escucha inválida: \(bindAddress)") }
        var address = sockaddr_in(sin_len: UInt8(MemoryLayout<sockaddr_in>.size), sin_family: sa_family_t(AF_INET), sin_port: port.bigEndian, sin_addr: in_addr(s_addr: resolvedAddress), sin_zero: (0,0,0,0,0,0,0,0))
        let bound = withUnsafePointer(to: &address) { $0.withMemoryRebound(to: sockaddr.self, capacity: 1) { bind(socketFD, $0, socklen_t(MemoryLayout<sockaddr_in>.size)) } }
        guard bound == 0, listen(socketFD, 16) == 0 else { close(socketFD); throw ScoutError.commandFailed("No se pudo enlazar el puerto \(port)") }
        while true {
            let client = accept(socketFD, nil, nil)
            if client >= 0 { DispatchQueue.global(qos: .userInitiated).async { [weak self] in guard let self else { close(client); return }; self.handle(client); close(client) } }
        }
    }

    private func startTLS() throws {
        guard let certPath = tlsCertPath, let keyPath = tlsKeyPath else { throw ScoutError.commandFailed("TLS requiere cert y key") }
        let certURL = URL(fileURLWithPath: certPath); let keyURL = URL(fileURLWithPath: keyPath)
        let identity = try createIdentity(cert: certURL, key: keyURL)
        let tlsOptions = NWProtocolTLS.Options()
        sec_protocol_options_set_local_identity(tlsOptions.securityProtocolOptions, identity)
        let tcpOptions = NWProtocolTCP.Options()
        let params = NWParameters(tls: tlsOptions, tcp: tcpOptions)
        params.allowLocalEndpointReuse = true
        let listener = try NWListener(using: params, on: NWEndpoint.Port(rawValue: port)!)
        listener.newConnectionHandler = { [weak self] connection in
            connection.start(queue: DispatchQueue.global(qos: .userInitiated))
            self?.handleTLSConnection(connection)
        }
        listener.start(queue: .main)
        dispatchMain()
    }

    private func createIdentity(cert: URL, key: URL) throws -> sec_identity_t {
        let certData = try Data(contentsOf: cert)
        let certRef = SecCertificateCreateWithData(nil, certData as CFData)
        guard let certRef else { throw ScoutError.commandFailed("No se pudo cargar el certificado TLS") }
        var identityRef: CFTypeRef?
        let query: [String: Any] = [kSecClass as String: kSecClassIdentity, kSecMatchLimit as String: kSecMatchLimitOne, kSecReturnRef as String: true]
        let status = SecItemCopyMatching(query as CFDictionary, &identityRef)
        if status == errSecSuccess, let secIdentity = identityRef as! SecIdentity? { return sec_identity_create(secIdentity)! }
        throw ScoutError.commandFailed("No se pudo crear identidad TLS; importa el certificado al Keychain primero")
    }

    private func handleTLSConnection(_ connection: NWConnection) {
        connection.receive(minimumIncompleteLength: 1, maximumLength: 8_388_608) { [weak self] data, _, _, error in
            guard let self, let data, error == nil else { connection.cancel(); return }
            let raw = String(data: data, encoding: .utf8) ?? ""
            let parts = raw.components(separatedBy: "\r\n\r\n")
            let head = parts[0].split(separator: "\r\n", omittingEmptySubsequences: false)
            guard let request = head.first?.split(separator: " "), request.count >= 2 else { connection.cancel(); return }
            let body = parts.dropFirst().joined(separator: "\r\n\r\n")
            let method = String(request[0]); let path = String(request[1])
            let authorization = head.dropFirst().first { String($0).lowercased().hasPrefix("authorization:") }.map { String($0).split(separator: ":", maxSplits: 1).dropFirst().joined().trimmingCharacters(in: .whitespaces) }
            let startedAt = Date(); let traceID = UUID().uuidString
            do { try self.respondTLS(connection, method: method, path: path, body: body, authorization: authorization); self.logRequest(method: method, path: path, status: 200, error: nil, traceID: traceID, durationMilliseconds: self.elapsedMilliseconds(since: startedAt)) } catch let error as ScoutError { self.sendTLS(connection, status: error.httpStatus, contentType: "application/json", data: self.json(["value": Self.errorValue(error)])); self.logRequest(method: method, path: path, status: error.httpStatus, error: error.localizedDescription, traceID: traceID, durationMilliseconds: self.elapsedMilliseconds(since: startedAt)) } catch { self.sendTLS(connection, status: 500, contentType: "application/json", data: self.json(["value": ["error": "unknown error", "message": error.localizedDescription]])); self.logRequest(method: method, path: path, status: 500, error: error.localizedDescription, traceID: traceID, durationMilliseconds: self.elapsedMilliseconds(since: startedAt)) }
        }
    }

    private func respondTLS(_ connection: NWConnection, method: String, path: String, body: String, authorization: String?) throws {
        let components = URLComponents(string: path); let routePath = components?.path ?? path; let rawPieces = routePath.split(separator: "/").map(String.init); let pieces = rawPieces.count >= 2 && rawPieces[0].lowercased() == "wd" && rawPieces[1].lowercased() == "hub" ? Array(rawPieces.dropFirst(2)) : rawPieces
        if method == "GET" && pieces == ["status"] { sendTLS(connection, status: 200, contentType: "application/json", data: json(["ready": true, "name": "CuyScout", "value": ["ready": true, "message": "CuyScout is ready", "build": "0.1.0"]])); return }
        sendTLS(connection, status: 200, contentType: "application/json", data: json(["ready": true, "value": ["message": "CuyScout TLS"]]))
    }

    private func sendTLS(_ connection: NWConnection, status: Int, contentType: String, data: Data) {
        let reason = status == 200 ? "OK" : status == 201 ? "Created" : status == 400 ? "Bad Request" : status == 404 ? "Not Found" : "Internal Server Error"
        let text = "HTTP/1.1 \(status) \(reason)\r\nContent-Type: \(contentType)\r\nContent-Length: \(data.count)\r\nConnection: close\r\n\r\n"
        let header = text.data(using: .utf8) ?? Data()
        connection.send(content: header + data, completion: .contentProcessed { _ in connection.cancel() })
    }

    private func handle(_ fd: Int32) {
        var noSignal: Int32 = 1
        setsockopt(fd, SOL_SOCKET, SO_NOSIGPIPE, &noSignal, socklen_t(MemoryLayout<Int32>.size))
        var timeout = timeval(tv_sec: 15, tv_usec: 0)
        setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &timeout, socklen_t(MemoryLayout<timeval>.size))
        var message = HTTPRequestBuffer()
        var buffer = [UInt8](repeating: 0, count: 16_384)
        let deadline = Date().addingTimeInterval(15)
        do {
            while true {
                guard Date() < deadline else { throw ScoutError.invalidRequest("Incomplete HTTP request timed out") }
                let count = read(fd, &buffer, buffer.count)
                if count < 0 && errno == EINTR { continue }
                guard count > 0 else { return }
                if try message.append(Data(buffer[..<count])) { break }
            }
        } catch {
            send(fd, status: 400, contentType: "application/json", data: json(["value": ["error":"invalid argument", "message":error.localizedDescription]]))
            return
        }
        let raw = String(decoding: message.data.prefix(message.messageLength!), as: UTF8.self); let parts = raw.components(separatedBy: "\r\n\r\n"); let head = parts[0].split(separator: "\r\n", omittingEmptySubsequences: false); guard let request = head.first?.split(separator: " "), request.count >= 2 else { return }
        let body = parts.dropFirst().joined(separator: "\r\n\r\n"); let method = String(request[0]); let path = String(request[1]); let authorization = head.dropFirst().first { String($0).lowercased().hasPrefix("authorization:") }.map { String($0).split(separator: ":", maxSplits: 1).dropFirst().joined().trimmingCharacters(in: .whitespaces) }; let websocketKey = head.dropFirst().first { String($0).lowercased().hasPrefix("sec-websocket-key:") }.map { String($0).split(separator: ":", maxSplits: 1).dropFirst().joined().trimmingCharacters(in: .whitespaces) }
        let startedAt = Date(); let traceID = UUID().uuidString
        do { try respond(fd, method: method, path: path, body: body, authorization: authorization, websocketKey: websocketKey); logRequest(method: method, path: path, status: 200, error: nil, traceID: traceID, durationMilliseconds: elapsedMilliseconds(since: startedAt)) } catch let error as ScoutError { send(fd, status: error.httpStatus, contentType: "application/json", data: json(["value": Self.errorValue(error)])); logRequest(method: method, path: path, status: error.httpStatus, error: error.localizedDescription, traceID: traceID, durationMilliseconds: elapsedMilliseconds(since: startedAt)) } catch { send(fd, status: 500, contentType: "application/json", data: json(["value": ["error": "unknown error", "message": error.localizedDescription]])); logRequest(method: method, path: path, status: 500, error: error.localizedDescription, traceID: traceID, durationMilliseconds: elapsedMilliseconds(since: startedAt)) }
    }

    private func respond(_ fd: Int32, method: String, path: String, body: String, authorization: String?, websocketKey: String? = nil) throws {
        let components = URLComponents(string: path); let routePath = components?.path ?? path; let rawPieces = routePath.split(separator: "/").map(String.init); let pieces = rawPieces.count >= 2 && rawPieces[0].lowercased() == "wd" && rawPieces[1].lowercased() == "hub" ? Array(rawPieces.dropFirst(2)) : rawPieces
        if token != nil && pieces != ["status"] && pieces != ["doctor"] { guard authorization == "Bearer \(token!)" else { throw ScoutError.invalidRequest("Authorization Bearer token required") }; let required = requiredScope(method: method, pieces: pieces); guard hasScope(required) else { throw ScoutError.invalidRequest("Token scope required: \(required)") } }
        if method == "GET", let key = websocketKey, pieces.count == 4, pieces[0] == "session", pieces[2] == "events", pieces[3] == "websocket" { handleWebSocket(fd, sessionID: pieces[1], key: key, path: path); return }
        if method == "GET" && pieces == ["agent-help"] { send(fd, status: 200, contentType: "application/json", data: json(AgentContract.httpHelp)); return }
        if method == "GET" && pieces == ["status"] { send(fd, status: 200, contentType: "application/json", data: json(["ready": true, "name": "CuyScout", "agentHelp": "/agent-help", "value": ["ready": true, "message": "CuyScout is ready", "build": "0.1.0"]])); return }
        if method == "GET" && pieces.count == 3 && pieces[0] == "devices" && pieces[2] == "apps" { send(fd, status: 200, contentType: "application/json", data: json(["value": try JSONSerialization.jsonObject(with: JSONEncoder().encode(engine.installedApps(deviceID: pieces[1])))])); return }
        if method == "GET" && pieces == ["devices"] { send(fd, status: 200, contentType: "application/json", data: try JSONEncoder().encode(engine.listDevices())); return }
        if method == "GET" && pieces == ["sessions"] { send(fd, status: 200, contentType: "application/json", data: try JSONEncoder().encode(engine.activeSessions())); return }
        if method == "GET" && pieces == ["storage", "simulators"] { send(fd, status: 200, contentType: "application/json", data: try JSONEncoder().encode(engine.simulatorStorage())); return }
        if method == "POST" && pieces == ["devices", "boot"] { let input = try JSONSerialization.jsonObject(with: Data(body.utf8)) as? [String: Any] ?? [:]; guard let deviceID = input["deviceId"] as? String ?? input["udid"] as? String else { throw ScoutError.invalidRequest("boot requires deviceId") }; try engine.bootDevice(deviceID: deviceID); send(fd, status: 200, contentType: "application/json", data: json(["value": NSNull()])); return }
        if method == "POST" && pieces == ["devices", "shutdown"] { let input = try JSONSerialization.jsonObject(with: Data(body.utf8)) as? [String: Any] ?? [:]; guard let deviceID = input["deviceId"] as? String ?? input["udid"] as? String else { throw ScoutError.invalidRequest("shutdown requires deviceId") }; try engine.shutdownDevice(deviceID: deviceID); send(fd, status: 200, contentType: "application/json", data: json(["value": NSNull()])); return }
        if method == "POST" && pieces == ["devices", "erase"] { let input = try JSONSerialization.jsonObject(with: Data(body.utf8)) as? [String: Any] ?? [:]; guard let deviceID = input["deviceId"] as? String ?? input["udid"] as? String else { throw ScoutError.invalidRequest("erase requires deviceId") }; try engine.eraseDevice(deviceID: deviceID); send(fd, status: 200, contentType: "application/json", data: json(["value": NSNull()])); return }
        if method == "POST" && pieces == ["devices", "clone"] { let input = try JSONSerialization.jsonObject(with: Data(body.utf8)) as? [String: Any] ?? [:]; guard let deviceID = input["deviceId"] as? String ?? input["udid"] as? String, let name = input["name"] as? String else { throw ScoutError.invalidRequest("clone requires deviceId and name") }; send(fd, status: 200, contentType: "application/json", data: try JSONEncoder().encode(try engine.cloneDevice(sourceDeviceID: deviceID, name: name))); return }
        if method == "DELETE" && pieces.count == 2 && pieces[0] == "devices" { try engine.deleteDevice(deviceID: pieces[1]); send(fd, status: 200, contentType: "application/json", data: json(["value": NSNull()])); return }
        if method == "POST" && pieces == ["devices", "create"] { let input = try JSONSerialization.jsonObject(with: Data(body.utf8)) as? [String: Any] ?? [:]; guard let name = input["name"] as? String, let runtime = input["runtime"] as? String else { throw ScoutError.invalidRequest("create requires name and runtime") }; send(fd, status: 201, contentType: "application/json", data: try JSONEncoder().encode(try engine.createDevice(name: name, runtime: runtime))); return }
        if method == "POST" && pieces == ["devices", "rename"] { let input = try JSONSerialization.jsonObject(with: Data(body.utf8)) as? [String: Any] ?? [:]; guard let deviceID = input["deviceId"] as? String ?? input["udid"] as? String, let name = input["name"] as? String else { throw ScoutError.invalidRequest("rename requires deviceId and name") }; try engine.renameDevice(deviceID: deviceID, name: name); send(fd, status: 200, contentType: "application/json", data: json(["value": NSNull()])); return }
        if pieces == ["decision", "laya"] && (method == "GET" || method == "POST") {
            if method == "POST" {
                let input = (try? JSONSerialization.jsonObject(with: Data(body.utf8))) as? [String: Any] ?? [:]
                guard input["enabled"] == nil || input["enabled"] is Bool else { throw ScoutError.invalidRequest("enabled debe ser true o false") }
                try LayaSwitch.shared.update(enabled: input["enabled"] as? Bool, url: input["url"] as? String)
            }
            let settings = LayaSwitch.shared.settings
            var value: [String: Any] = ["enabled": settings.enabled, "url": settings.url]
            if settings.enabled, let url = URL(string: settings.url) { let health = LayaService.health(url: url); value["available"] = health.reachable; value["loaded"] = health.loaded }
            send(fd, status: 200, contentType: "application/json", data: json(["value": value])); return
        }
        if method == "GET" && pieces == ["doctor"] { send(fd, status: 200, contentType: "application/json", data: try JSONEncoder().encode(engine.doctor())); return }
        if method == "GET" && pieces == ["conformance"] { send(fd, status: 200, contentType: "application/json", data: try JSONEncoder().encode(engine.conformanceSnapshot())); return }
        if method == "GET" && pieces == ["lessons"] { let query = components?.queryItems ?? []; let limit = Int(query.first(where: { $0.name == "limit" })?.value ?? "50") ?? 50; let tags = query.filter { $0.name == "tags" }.compactMap(\.value).flatMap { $0.split(separator: ",").map(String.init) }; let scope = query.first(where: { $0.name == "scope" })?.value.flatMap(LessonScope.init(rawValue:)); send(fd, status: 200, contentType: "application/json", data: try JSONEncoder().encode(engine.allLessons(query: query.first(where: { $0.name == "q" })?.value, tags: tags, scope: scope, limit: limit, includeDiscarded: query.contains { $0.name == "includeDiscarded" && $0.value == "true" }))); return }
        if method == "POST" && pieces.count == 3 && pieces[0] == "lessons" && pieces[2] == "feedback" {
            let input = try JSONSerialization.jsonObject(with: Data(body.utf8)) as? [String: Any] ?? [:]
            guard let outcome = input["outcome"] as? String, ["helped", "failed"].contains(outcome) else { throw ScoutError.invalidRequest("outcome debe ser helped o failed") }
            send(fd, status: 200, contentType: "application/json", data: try JSONEncoder().encode(engine.lessonFeedback(id: pieces[1], helped: outcome == "helped", sessionID: input["sessionId"] as? String))); return
        }
        if method == "POST" && pieces == ["lessons"] { let input = try JSONSerialization.jsonObject(with: Data(body.utf8)) as? [String: Any] ?? [:]; guard let rawScope = input["scope"] as? String, let scope = LessonScope(rawValue: rawScope), let title = input["title"] as? String, let observation = input["observation"] as? String, let recommendation = input["recommendation"] as? String else { throw ScoutError.invalidRequest("scope, title, observation y recommendation son obligatorios") }; let lesson = try engine.recordLesson(scope: scope, sessionID: input["sessionId"] as? String, title: title, observation: observation, recommendation: recommendation, evidence: input["evidence"] as? String, tags: input["tags"] as? [String] ?? [], confidence: input["confidence"] as? Double ?? 0.8); send(fd, status: 201, contentType: "application/json", data: try JSONEncoder().encode(lesson)); return }
        if method == "GET" && pieces == ["drivers"] { send(fd, status: 200, contentType: "application/json", data: json(["drivers": try JSONSerialization.jsonObject(with: JSONEncoder().encode(engine.drivers())), "health": try JSONSerialization.jsonObject(with: JSONEncoder().encode(engine.driverHealth()))])); return }
        if method == "GET" && pieces == ["drivers", "manifests"] { send(fd, status: 200, contentType: "application/json", data: try JSONEncoder().encode(engine.driverManifests())); return }
        if method == "POST" && pieces == ["drivers", "manifests"] { let manifest = try JSONDecoder().decode(DriverManifest.self, from: Data(body.utf8)); engine.registerDriverManifest(manifest); send(fd, status: 201, contentType: "application/json", data: try JSONEncoder().encode(manifest)); return }
        if method == "POST" && pieces == ["drivers", "load"] { let manifest = try JSONDecoder().decode(DriverManifest.self, from: Data(body.utf8)); let result = engine.loadDriverFromManifest(manifest); send(fd, status: result.loaded ? 200 : 400, contentType: "application/json", data: try JSONEncoder().encode(result)); return }
        if method == "GET" && pieces == ["scheduler"] { send(fd, status: 200, contentType: "application/json", data: json(["leases": engine.schedulerStatus(), "leaseDetails": try JSONSerialization.jsonObject(with: JSONEncoder().encode(engine.schedulerLeases())), "ports": engine.schedulerPortStatus()])); return }
        if method == "GET" && pieces == ["scheduler", "queue"] { send(fd, status: 200, contentType: "application/json", data: try JSONEncoder().encode(engine.sessionQueueSnapshot())); return }
        if method == "POST" && pieces == ["scheduler", "queue"] { let input = try JSONSerialization.jsonObject(with: Data(body.utf8)) as? [String: Any] ?? [:]; let priority = (input["priority"] as? String).flatMap(SessionPriority.init(rawValue:)) ?? .normal; let entry = engine.enqueueSession(deviceID: input["deviceId"] as? String, bundleIdentifier: input["bundleIdentifier"] as? String, driverID: input["driverId"] as? String ?? "ios-simulator", priority: priority); send(fd, status: 201, contentType: "application/json", data: try JSONEncoder().encode(entry)); return }
        if method == "DELETE" && pieces.count == 3 && pieces[0] == "scheduler" && pieces[1] == "queue" { let cancelled = engine.cancelQueuedSession(sessionID: pieces[2]); send(fd, status: cancelled ? 200 : 404, contentType: "application/json", data: json(["cancelled": cancelled])); return }
        if method == "GET" && pieces == ["dashboard"] { send(fd, status: 200, contentType: "application/json", data: try JSONEncoder().encode(try engine.fleetDashboard())); return }
        if method == "GET" && pieces == ["workers"] { send(fd, status: 200, contentType: "application/json", data: try JSONEncoder().encode(engine.farmWorkersStatus())); return }
        if method == "POST" && pieces == ["workers"] { let input = try JSONSerialization.jsonObject(with: Data(body.utf8)) as? [String: Any] ?? [:]; guard let url = input["url"] as? String else { throw ScoutError.invalidRequest("workers requires url") }; let worker = try engine.registerFarmWorker(url: url, capabilities: input["capabilities"] as? [String] ?? [], maxSessions: input["maxSessions"] as? Int ?? 4); send(fd, status: 201, contentType: "application/json", data: try JSONEncoder().encode(worker)); return }
        if method == "POST" && pieces.count == 3 && pieces[0] == "workers" && pieces[2] == "heartbeat" { let input = try JSONSerialization.jsonObject(with: Data(body.utf8)) as? [String: Any] ?? [:]; let worker = try engine.farmWorkerHeartbeat(workerID: pieces[1], activeSessions: input["activeSessions"] as? Int); send(fd, status: 200, contentType: "application/json", data: try JSONEncoder().encode(worker)); return }
        if method == "DELETE" && pieces.count == 2 && pieces[0] == "workers" { let removed = engine.deregisterFarmWorker(workerID: pieces[1]); send(fd, status: removed ? 200 : 404, contentType: "application/json", data: json(["removed": removed])); return }
        if method == "GET" && pieces == ["app-cache"] { send(fd, status: 200, contentType: "application/json", data: try JSONEncoder().encode(engine.appCacheList())); return }
        if method == "POST" && pieces == ["app-cache"] { let input = try JSONSerialization.jsonObject(with: Data(body.utf8)) as? [String: Any] ?? [:]; guard let bundle = input["bundleId"] as? String, let path = input["path"] as? String else { throw ScoutError.invalidRequest("app-cache requires bundleId and path") }; send(fd, status: 201, contentType: "application/json", data: try JSONEncoder().encode(engine.cacheApp(bundleIdentifier: bundle, path: path))); return }
        if method == "DELETE" && pieces == ["app-cache"] { engine.clearAppCache(); send(fd, status: 200, contentType: "application/json", data: json(["cleared": true])); return }
        if method == "DELETE" && pieces.count == 2 && pieces[0] == "app-cache" { engine.clearAppCache(bundleIdentifier: pieces[1]); send(fd, status: 200, contentType: "application/json", data: json(["cleared": true])); return }
        if method == "GET" && pieces == ["metrics"] { let prometheus = URLComponents(string: "http://localhost\(path)")?.queryItems?.contains { $0.name == "format" && $0.value == "prometheus" } == true; if prometheus { send(fd, status: 200, contentType: "text/plain; version=0.0.4", data: Data(engine.fleetMetricsPrometheus().utf8)) } else { send(fd, status: 200, contentType: "application/json", data: try JSONEncoder().encode(engine.fleetMetrics())) }; return }
        if method == "GET" && pieces == ["plugins"] { send(fd, status: 200, contentType: "application/json", data: try JSONEncoder().encode(engine.plugins())); return }
        if method == "GET" && pieces == ["plugins", "routes"] { send(fd, status: 200, contentType: "application/json", data: try JSONEncoder().encode(engine.pluginRoutes())); return }
        if let routeResult = try engine.handlePluginRoute(method: method, path: routePath, body: body, sessionID: pieces.count >= 2 && pieces[0] == "session" ? pieces[1] : nil) { send(fd, status: routeResult.status, contentType: routeResult.contentType, data: routeResult.body); return }
        if method == "GET" && pieces == ["artifacts"] { send(fd, status: 200, contentType: "application/json", data: json(["value": engine.persistedArtifacts()])); return }
        if method == "GET" && pieces == ["artifacts", "catalog"] { send(fd, status: 200, contentType: "application/json", data: try JSONEncoder().encode(engine.artifactCatalog())); return }
        if method == "GET" && pieces == ["artifacts", "status"] { send(fd, status: 200, contentType: "application/json", data: try JSONEncoder().encode(engine.artifactStoreStatus())); return }
        if method == "DELETE" && pieces.count == 2 && pieces[0] == "artifacts" { try engine.deletePersistedArtifact(sessionID: pieces[1]); send(fd, status: 200, contentType: "application/json", data: json(["deleted": true])); return }
        if method == "POST" && pieces == ["artifacts", "import"] {
            guard let data = body.data(using: .utf8), !data.isEmpty else { throw ScoutError.invalidRequest("Artifact body is required") }
            let overwrite = components?.queryItems?.contains { $0.name == "overwrite" && $0.value == "true" } == true
            send(fd, status: 201, contentType: "application/json", data: try JSONEncoder().encode(engine.importPersistedArtifact(data, overwrite: overwrite))); return
        }
        if method == "POST" && pieces.count == 3 && pieces[0] == "artifacts" && pieces[2] == "restore" { let session = try engine.restorePersistedArtifact(sessionID: pieces[1]); send(fd, status: 200, contentType: "application/json", data: try JSONEncoder().encode(session)); return }
        if method == "POST" && pieces.count == 4 && pieces[0] == "artifacts" && pieces[2] == "replay" && pieces[3] == "preflight" {
            let input = try JSONDecoder().decode(ArtifactReplayRequest.self, from: Data((body.isEmpty ? "{}" : body).utf8))
            let result = try engine.preflightReplay(sessionID: pieces[1], deviceID: input.deviceID, preparation: input.preparation ?? (input.resetApp == false ? .preserve : .restart), appPath: input.appPath, variables: input.variables ?? [:], optimized: input.optimized ?? false)
            send(fd, status: 200, contentType: "application/json", data: try JSONEncoder().encode(result)); return
        }
        if method == "POST" && pieces.count == 3 && pieces[0] == "artifacts" && pieces[2] == "replay" {
