    private func w3cActions(from input: [String: Any], sessionID: String) throws -> [ScoutAction] {
        var result: [ScoutAction] = []
        guard let sources = input["actions"] as? [[String: Any]] else { throw ScoutError.invalidRequest("W3C actions must be an array") }
        for source in sources {
            guard let type = source["type"] as? String, let actions = source["actions"] as? [[String: Any]] else { continue }
            if type == "key" { let text = actions.compactMap { $0["value"] as? String }.joined(); if !text.isEmpty { result.append(.type(text)) }; continue }
            if type == "wheel" { for item in actions { if let itemType = item["type"] as? String, itemType == "scroll", let x = item["x"] as? Double, let y = item["y"] as? Double { result.append(.scroll(x: x, y: y)) } }; continue }
            var points: [(Double, Double)] = []; var pressed = false
            for item in actions {
                guard let itemType = item["type"] as? String else { continue }
                if itemType == "pause", let duration = item["duration"] as? Double { Thread.sleep(forTimeInterval: duration / 1000.0); continue }
                if itemType == "pointerMove", let x = item["x"] as? Double, let y = item["y"] as? Double {
                    if let origin = item["origin"] as? [String: Any], let elementID = origin["element-6066-11e4-a52e-4f735466cecf"] as? String ?? origin["ELEMENT"] as? String {
                        if let rectData = try? engine.performElementAction(sessionID: sessionID, elementID: elementID, action: { .elementRect($0) }), let rect = (try? JSONSerialization.jsonObject(with: rectData ?? Data())) as? [String: Any], let value = rect["value"] as? [String: Any] {
                            let ox = (value["x"] as? Double) ?? 0; let oy = (value["y"] as? Double) ?? 0; points.append((ox + x, oy + y)); continue
                        }
                    }
                    points.append((x, y))
                }
                if itemType == "pointerDown" { pressed = true }
                if itemType == "pointerUp" && pressed { guard let start = points.first, let end = points.last else { continue }; if start.0 == end.0 && start.1 == end.1 { result.append(.tap(x: start.0, y: start.1)) } else { result.append(.swipe(fromX: start.0, fromY: start.1, toX: end.0, toY: end.1, duration: 0.3)) }; pressed = false }
            }
        }
        guard !result.isEmpty else { throw ScoutError.invalidRequest("No supported W3C actions found") }
        return result
    }
    private func configuredScopes() -> Set<String> { let raw = ProcessInfo.processInfo.environment["CUYSCOUT_TOKEN_SCOPES"]?.split(separator: ",").map { $0.trimmingCharacters(in: .whitespacesAndNewlines).lowercased() } ?? []; return raw.isEmpty ? ["admin", "execute", "read"] : Set(raw) }
    private func hasScope(_ required: String) -> Bool { let scopes = configuredScopes(); return scopes.contains("admin") || scopes.contains(required) }
    private func requiredScope(method: String, pieces: [String]) -> String { if pieces.contains("security-policy") || pieces.contains("security-audit") || (method == "POST" && pieces == ["decision", "laya"]) || pieces == ["drivers"] || pieces == ["plugins"] || pieces == ["artifacts", "status"] || (method == "DELETE" && (pieces.first == "artifacts" || pieces.first == "devices")) { return "admin" }; return method == "GET" ? "read" : "execute" }
    /// Cuerpo W3C del error más `hint`, el siguiente paso recomendado para el agente.
    static func errorValue(_ error: ScoutError) -> [String: Any] {
        var value: [String: Any] = ["error": error.w3cCode, "message": error.localizedDescription]
        if let hint = error.hint { value["hint"] = hint }
        return value
    }

    private func logRequest(method: String, path: String, status: Int, error: String?, traceID: String, durationMilliseconds: Int) { guard ProcessInfo.processInfo.environment["CUYSCOUT_LOG_FORMAT"]?.lowercased() == "json" else { return }; var entry: [String: Any] = ["timestamp": ISO8601DateFormatter().string(from: Date()), "trace_id": traceID, "method": method, "path": URLComponents(string: "http://localhost\(path)")?.path ?? path, "status": status, "duration_ms": durationMilliseconds]; if let error { entry["error"] = error }; guard let data = try? JSONSerialization.data(withJSONObject: entry), let line = String(data: data, encoding: .utf8) else { return }; FileHandle.standardError.write(Data((line + "\n").utf8)) }
